// Set a socket option with a generic buffer; library validates level/option/size.
if (!FUZZ_GET_ATTR_INT(so, "valid")) { FUZZ_BAIL(); }

// Randomly pick level/option; values are library-validated. Use benign buffer.
int level = (int)(*FUZZ_PARAM(unsigned int));
int optname = (int)(*FUZZ_PARAM(unsigned int));

// Provide a small options buffer (<= 256 bytes) with arbitrary contents.
size_t buflen = (size_t)(*FUZZ_PARAM(unsigned int) % 256u);
if (buflen == 0) buflen = 1; // must be at least 1 byte
std::string optbuf = FUZZ_PARAM_STR();
optbuf.resize(buflen);

int rc = usrsctp_setsockopt((struct socket *)so, level, optname, (const void *)optbuf.data(), (socklen_t)optbuf.size());
// It's valid for the API to reject unsupported options; treat errors as acceptable.
(void)rc;

// Validation: We keep ownership of 'so' and return it; option buffer is ephemeral and sized correctly.

// Get a socket option; provide a writable buffer and length in/out.
if (!FUZZ_GET_ATTR_INT(so, "valid")) { FUZZ_BAIL(); }

int level = (int)(*FUZZ_PARAM(unsigned int));
int optname = (int)(*FUZZ_PARAM(unsigned int));

// Allocate an output buffer and a length holder.
std::vector<uint8_t> outbuf(256u, 0);
socklen_t optlen = (socklen_t)outbuf.size();

int rc = usrsctp_getsockopt((struct socket *)so, level, optname, outbuf.data(), &optlen);
(void)rc; (void)optlen;

// Validation: Buffer is writable and length pointer is non-null; we preserve 'so' for pool reuse.

// Retrieve association-specific info into a caller-provided buffer.
if (!FUZZ_GET_ATTR_INT(so, "valid")) { FUZZ_BAIL(); }

sctp_assoc_t assoc_id = (sctp_assoc_t)(*FUZZ_PARAM(uint32_t));
int opt = (int)(*FUZZ_PARAM(unsigned int));

std::vector<uint8_t> buf(256u, 0);
socklen_t sz = (socklen_t)buf.size();
int rc = usrsctp_opt_info((struct socket *)so, assoc_id, opt, buf.data(), &sz);
(void)rc; (void)sz;

// Validation: We pass a valid writable buffer and size pointer; 'so' life is preserved.

// Obtain peer addresses for an association; on success the library allocates memory to be freed via usrsctp_freepaddrs().
if (!FUZZ_GET_ATTR_INT(so, "valid")) { FUZZ_BAIL(); }

sctp_assoc_t assoc_id = (sctp_assoc_t)(*FUZZ_PARAM(uint32_t));
struct sockaddr *raddrs = nullptr;
int n = usrsctp_getpaddrs((struct socket *)so, assoc_id, &raddrs);
if (n <= 0 || raddrs == nullptr) { FUZZ_BAIL(); }

void *addrs = (void *)raddrs;
// Tag the returned pointer so only the correct free API is used later.
FUZZ_SET_ATTR_INT(addrs, "is_paddrs", 1);
FUZZ_SET_ATTR_INT(addrs, "count", n);

// Validation: We ensure success and tag for proper lifetime management.

// Free memory returned by usrsctp_getpaddrs().
if (!addrs) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT(addrs, "is_paddrs")) { FUZZ_BAIL(); }

usrsctp_freepaddrs((struct sockaddr *)addrs);

// Validation: Attribute check prevents freeing arbitrary pointers; no outputs returned.

// Obtain local addresses; must be freed via usrsctp_freeladdrs().
if (!FUZZ_GET_ATTR_INT(so, "valid")) { FUZZ_BAIL(); }

sctp_assoc_t assoc_id = (sctp_assoc_t)(*FUZZ_PARAM(uint32_t));
struct sockaddr *raddrs = nullptr;
int n = usrsctp_getladdrs((struct socket *)so, assoc_id, &raddrs);
if (n <= 0 || raddrs == nullptr) { FUZZ_BAIL(); }

void *addrs = (void *)raddrs;
FUZZ_SET_ATTR_INT(addrs, "is_laddrs", 1);
FUZZ_SET_ATTR_INT(addrs, "count", n);

// Validation: We ensure success and tag pointer for correct free routine.

// Free memory returned by usrsctp_getladdrs().
if (!addrs) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT(addrs, "is_laddrs")) { FUZZ_BAIL(); }

usrsctp_freeladdrs((struct sockaddr *)addrs);

// Validation: Attribute check ensures only correct pointers are freed.

// Send a message with extended options. The library validates addresses and info.
if (!FUZZ_GET_ATTR_INT(so, "valid")) { FUZZ_BAIL(); }

// Prepare payload (limit size for fuzzer performance).
std::string payload = FUZZ_PARAM_STR();
if (payload.size() > 512) payload.resize(512);
const void *data = payload.data();
size_t len = payload.size();

// Optionally provide a destination address array (we use NULL to avoid invalid sockaddr layout issues on differing platforms).
struct sockaddr *to = nullptr;
int addrcnt = 0;

// Choose infotype and prepare corresponding structure and length.
unsigned int choice = *FUZZ_PARAM(unsigned int) % 5u;
unsigned int infotype = 0; // SCTP_SENDV_NOINFO
std::vector<uint8_t> infobuf;
socklen_t infolen = 0;
if (choice == 1) {
    // SNDINFO
    struct sctp_sndinfo si{};
    si.snd_sid = (uint16_t)(*FUZZ_PARAM(unsigned int));
    si.snd_flags = (uint16_t)(*FUZZ_PARAM(unsigned int));
    si.snd_ppid = (uint32_t)(*FUZZ_PARAM(uint32_t));
    si.snd_context = (uint32_t)(*FUZZ_PARAM(uint32_t));
    si.snd_assoc_id = (sctp_assoc_t)(*FUZZ_PARAM(uint32_t));
    infobuf.assign((uint8_t *)&si, (uint8_t *)&si + sizeof(si));
    infotype = 1; // SCTP_SENDV_SNDINFO
    infolen = (socklen_t)infobuf.size();
} else if (choice == 2) {
    // PRINFO
    struct sctp_prinfo pi{};
    pi.pr_policy = (uint16_t)(*FUZZ_PARAM(unsigned int));
    pi.pr_value = (uint32_t)(*FUZZ_PARAM(uint32_t));
    infobuf.assign((uint8_t *)&pi, (uint8_t *)&pi + sizeof(pi));
    infotype = 2; // SCTP_SENDV_PRINFO
    infolen = (socklen_t)infobuf.size();
} else if (choice == 3) {
    // AUTHINFO
    struct sctp_authinfo ai{};
    ai.auth_keynumber = (uint16_t)(*FUZZ_PARAM(unsigned int));
    infobuf.assign((uint8_t *)&ai, (uint8_t *)&ai + sizeof(ai));
    infotype = 3; // SCTP_SENDV_AUTHINFO
    infolen = (socklen_t)infobuf.size();
} else if (choice == 4) {
    // SPA (composite)
    struct sctp_sendv_spa spa{};
    spa.sendv_flags = (uint32_t)(*FUZZ_PARAM(uint32_t));
    spa.sendv_sndinfo.snd_sid = (uint16_t)(*FUZZ_PARAM(unsigned int));
    spa.sendv_sndinfo.snd_flags = (uint16_t)(*FUZZ_PARAM(unsigned int));
    spa.sendv_sndinfo.snd_ppid = (uint32_t)(*FUZZ_PARAM(uint32_t));
    spa.sendv_sndinfo.snd_context = (uint32_t)(*FUZZ_PARAM(uint32_t));
    spa.sendv_sndinfo.snd_assoc_id = (sctp_assoc_t)(*FUZZ_PARAM(uint32_t));
    spa.sendv_prinfo.pr_policy = (uint16_t)(*FUZZ_PARAM(unsigned int));
    spa.sendv_prinfo.pr_value = (uint32_t)(*FUZZ_PARAM(uint32_t));
    spa.sendv_authinfo.auth_keynumber = (uint16_t)(*FUZZ_PARAM(unsigned int));
    infobuf.assign((uint8_t *)&spa, (uint8_t *)&spa + sizeof(spa));
    infotype = 5; // SCTP_SENDV_SPA (value assumed for harness; library validates)
    infolen = (socklen_t)infobuf.size();
}

int flags = (int)(*FUZZ_PARAM(unsigned int));

ssize_t sent = usrsctp_sendv((struct socket *)so, data, len, to, addrcnt,
                             infobuf.empty() ? nullptr : (void *)infobuf.data(),
                             infolen, infotype, flags);
(void)sent;

// Validation: We pass either NULL info or a correctly sized info struct matching the chosen infotype; socket remains owned and returned.

// Receive a message with extended receive options.
if (!FUZZ_GET_ATTR_INT(so, "valid")) { FUZZ_BAIL(); }

// Data buffer for receive.
std::vector<uint8_t> dbuf(512u, 0);

// Optional source address output.
struct sockaddr_storage from_storage{};
struct sockaddr *from = nullptr;
socklen_t fromlen = 0;
if ((*FUZZ_PARAM(unsigned int) & 1u) != 0u) {
    from = (struct sockaddr *)&from_storage;
    fromlen = (socklen_t)sizeof(from_storage);
}

// Optional ancillary info.
unsigned int requested_infotype = (*FUZZ_PARAM(unsigned int) % 4u); // 0..3 corresponds to NOINFO/RCVINFO/NXTINFO/RN
std::vector<uint8_t> info_buf;
socklen_t infolen = 0;
if (requested_infotype == 1) {
    info_buf.resize(sizeof(struct sctp_rcvinfo));
    infolen = (socklen_t)info_buf.size();
} else if (requested_infotype == 2) {
    info_buf.resize(sizeof(struct sctp_nxtinfo));
    infolen = (socklen_t)info_buf.size();
} else if (requested_infotype == 3) {
    info_buf.resize(sizeof(struct sctp_recvv_rn));
    infolen = (socklen_t)info_buf.size();
}
unsigned int infotype = requested_infotype; // library sets actual type on return
int msg_flags = 0;

ssize_t n = usrsctp_recvv((struct socket *)so,
                          dbuf.data(), dbuf.size(),
                          from, (from ? &fromlen : nullptr),
                          info_buf.empty() ? nullptr : (void *)info_buf.data(),
                          info_buf.empty() ? nullptr : &infolen,
                          &infotype,
                          &msg_flags);
(void)n; (void)fromlen; (void)infolen; (void)infotype; (void)msg_flags;

// Validation: Buffers and length pointers are conditionally provided and sized; ownership of 'so' remains with harness.

// Bind a socket to a local address.
if (!FUZZ_GET_ATTR_INT(so, "valid")) { FUZZ_BAIL(); }

// Build a sockaddr_storage with fuzzed family/port; content is library-validated.
struct sockaddr_storage ss{};
// AF_INET=2 or AF_INET6=10 (common); library validates more strictly.
uint16_t fams[2] = {2, 10};
uint16_t family = fams[*FUZZ_PARAM(unsigned int) % 2];
((uint16_t *)&ss)[0] = family; // sa_family placement compatible at start

socklen_t namelen = (socklen_t)sizeof(ss);
int rc = usrsctp_bind((struct socket *)so, (struct sockaddr *)&ss, namelen);
(void)rc;

// Validation: Provide a buffer of sufficient size; on API failure we keep socket state unchanged.

// Bind or unbind multiple addresses.
if (!FUZZ_GET_ATTR_INT(so, "valid")) { FUZZ_BAIL(); }

// Prepare a single sockaddr_storage; addrcnt=1 to simplify layout correctness.
struct sockaddr_storage ss{};
uint16_t fams[2] = {2, 10};
uint16_t family = fams[*FUZZ_PARAM(unsigned int) % 2];
((uint16_t *)&ss)[0] = family;

int addrcnt = 1;
// Use typical flags: add(0x01) or remove(0x02); library validates exact constants.
int flags = ((*FUZZ_PARAM(unsigned int) & 1u) != 0u) ? 0x01 : 0x02;

int rc = usrsctp_bindx((struct socket *)so, (struct sockaddr *)&ss, addrcnt, flags);
(void)rc;

// Validation: The address array is a single, properly sized element; errors are acceptable.

