import random
import struct

# Helpers to build common SCTP ancillary structs with reasonable ranges.

def _u16(r):
    return r.randrange(0, 0x10000)

def _u32(r):
    return r.randrange(0, 0x100000000)


def build_sctp_sndinfo(r: random.Random) -> bytes:
    # struct sctp_sndinfo { uint16_t snd_sid; uint16_t snd_flags; uint32_t snd_ppid; uint32_t snd_context; sctp_assoc_t snd_assoc_id; };
    snd_sid = _u16(r)
    flags_candidates = [0, 1, 2, 4, 8, 0x10, 1 | 2, 1 | 0x10]
    snd_flags = r.choice(flags_candidates)
    snd_ppid = _u32(r)
    snd_context = _u32(r)
    snd_assoc_id = _u32(r)
    return struct.pack('<HHIII', snd_sid, snd_flags, snd_ppid, snd_context, snd_assoc_id)


def build_sctp_prinfo(r: random.Random) -> bytes:
    # struct sctp_prinfo { uint16_t pr_policy; uint32_t pr_value; };
    pr_policy = r.choice([0, 1, 2, 3, _u16(r)])
    pr_value = r.choice([0, 1, 10, 100, 1000, 5000, _u32(r)])
    return struct.pack('<HI', pr_policy, pr_value)


def build_sctp_authinfo(r: random.Random) -> bytes:
    # struct sctp_authinfo { uint16_t auth_keynumber; };
    return struct.pack('<H', _u16(r))


def build_sctp_sendv_spa(r: random.Random) -> bytes:
    # struct sctp_sendv_spa { uint32_t sendv_flags; sctp_sndinfo; sctp_prinfo; sctp_authinfo; };
    flags = r.choice([0x01, 0x03, 0x07])
    return struct.pack('<I', flags) + build_sctp_sndinfo(r) + build_sctp_prinfo(r) + build_sctp_authinfo(r)


def build_sockopt_blob(r: random.Random) -> bytes:
    choice = r.randrange(0, 10)
    if choice == 0:
        return build_sctp_sndinfo(r)
    if choice == 1:
        return build_sctp_prinfo(r)
    if choice == 2:
        return build_sctp_authinfo(r)
    if choice == 3:
        return build_sctp_sendv_spa(r)
    if choice == 4:
        # sctp_rtoinfo { sctp_assoc_t id; uint32_t initial; max; min; }
        return struct.pack('<IIII', _u32(r), r.randrange(1, 3000), r.randrange(1000, 60000), r.randrange(10, 1000))
    if choice == 5:
        # sctp_initmsg { num_ostreams, max_instreams, max_attempts, max_init_timeo }
        vals = [r.randrange(1, 64), r.randrange(1, 64), r.randrange(1, 20), r.randrange(1, 60000)]
        return struct.pack('<HHHH', *vals)
    if choice == 6:
        # sctp_assoc_value { assoc_id; value }
        return struct.pack('<II', _u32(r), _u32(r))
    if choice == 7:
        # sctp_sack_info { assoc_id; delay; freq }
        return struct.pack('<III', _u32(r), r.randrange(0, 1000), r.randrange(0, 10))
    if choice == 8:
        # sctp_event { assoc_id; type; on }
        return struct.pack('<IHB', _u32(r), r.randrange(0, 0x400), r.randrange(0, 2))
    # default: small arbitrary but non-empty
    size = r.randrange(1, 64)
    return r.randbytes(size)


def generate(seed: int) -> bytes:
    r = random.Random(seed)

    segments = []

    # 1) Payload for sendv (<=512 bytes)
    pay_len = r.randrange(1, 513)
    modes_pool = ['zero', 'one', 'inc', 'rand', 'text']
    k = min(len(modes_pool), max(1, r.randrange(1, 4)))  # choose 1..3 modes
    modes = r.sample(modes_pool, k=k)
    buf = bytearray()
    # To avoid empty range in randrange, ensure upper bound >= 2
    per_mode_cap = max(2, pay_len // max(1, k))
    for idx, m in enumerate(modes):
        remaining = pay_len - len(buf)
        if remaining <= 0:
            break
        upper = min(remaining, per_mode_cap)
        # r.randrange requires start < stop; ensure stop >= 2
        if upper <= 1:
            part_len = remaining  # fill the rest
        else:
            part_len = r.randrange(1, upper)
        if m == 'zero':
            buf += b"\x00" * part_len
        elif m == 'one':
            buf += b"\xFF" * part_len
        elif m == 'inc':
            start = r.randrange(0, 256)
            buf += bytes(((start + i) & 0xFF for i in range(part_len)))
        elif m == 'rand':
            buf += r.randbytes(part_len)
        elif m == 'text':
            text = ("SCTP-FUZZ-" + str(seed) + "-").encode('ascii')
            repeat = (part_len + len(text) - 1) // len(text)
            buf += (text * repeat)[:part_len]
    if len(buf) < pay_len:
        buf += r.randbytes(pay_len - len(buf))
    segments.append(bytes(buf[:pay_len]))

    # 2) Valid ancillary info structs for sendv
    segments.append(build_sctp_sndinfo(r))
    segments.append(build_sctp_prinfo(r))
    segments.append(build_sctp_authinfo(r))
    segments.append(build_sctp_sendv_spa(r))

    # 3) Sockopt blobs (1..256 bytes each)
    for _ in range(r.randrange(3, 7)):
        blob = build_sockopt_blob(r)
        if len(blob) > 256:
            blob = blob[:256]
        segments.append(blob)

    # 4) Buffer for crc32c path (<=1024)
    crc_len = r.randrange(0, 1025)
    segments.append(r.randbytes(crc_len))

    # 5) A few tiny non-empty blobs
    for _ in range(3):
        segments.append(r.randbytes(r.randrange(1, 17)))

    out = b''.join(segments)
    if len(out) > 4096:
        out = out[:4096]
    return out
